(() => {
 'use strict';
 const cfg=window.FULAB_CONFIG||{}, number=String(cfg.whatsapp||'').replace(/\D/g,'');
 const float=document.createElement('div');float.className='contact-float';float.setAttribute('aria-label','İletişim seçenekleri');
 const assistantLink=document.createElement('a');assistantLink.href='asistan.html';assistantLink.textContent='✦ Talebinizi anlatın';float.append(assistantLink);
 if(number){const wa=document.createElement('a');wa.href='https://wa.me/'+number;wa.target='_blank';wa.rel='noopener noreferrer';wa.className='wa-float';wa.setAttribute('aria-label','WhatsApp üzerinden FuLab ile iletişime geç');wa.innerHTML='<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M16 3a13 13 0 0 0-11.2 19.6L3 29l6.6-1.7A13 13 0 1 0 16 3zm0 2.2a10.8 10.8 0 1 1-5.5 20.1l-.4-.2-3.9 1 1-3.8-.3-.4A10.8 10.8 0 0 1 16 5.2zm-4.4 5.3c-.3 0-.6.1-.9.5-.3.3-1.2 1.1-1.2 2.7s1.2 3.1 1.4 3.3c.2.2 2.4 3.7 5.9 5.1 2.9 1.2 3.5.9 4.1.8.6-.1 1.9-.8 2.1-1.5.3-.8.3-1.4.2-1.5-.1-.2-.3-.3-.7-.5l-2.2-1c-.3-.1-.5-.2-.8.2l-1 1.2c-.2.2-.4.3-.7.1a9 9 0 0 1-2.6-1.6 10 10 0 0 1-1.8-2.2c-.2-.3 0-.5.1-.7l.7-.9c.2-.2.2-.5.1-.7l-1-2.4c-.2-.6-.5-.6-.8-.6z"/></svg><span class="wa-label">WhatsApp</span>';float.append(wa);}document.body.append(float);
 const root=document.querySelector('#fulab-assistant');if(!root)return;
 const q=s=>root.querySelector(s), online=/^https?:$/.test(location.protocol);
 const steps=[['sector','İşletmeniz hangi sektörde, ne iş yapıyorsunuz?'],['need','Hangi işi kolaylaştırmak veya otomatikleştirmek istiyorsunuz?'],['systems','Şu anda bu işi nasıl yapıyorsunuz; hangi programları kullanıyorsunuz?'],['goal','Beklediğiniz sonuç nedir? Yaklaşık iş hacmini de yazabilirsiniz.'],['timing','Ne zaman başlamayı düşünüyorsunuz? Belli değilse bunu yazabilirsiniz.']];
 let state={index:0,answers:{},caps:{ai:false,email:false},token:'',ai:false,busy:false}, boot=null;
 async function request(action,data={}){const r=await fetch('api/assistant.php'+(action==='status'?'?action=status':''),{method:action==='status'?'GET':'POST',headers:action==='status'?{}:{'Content-Type':'application/json','X-FuLab-Token':state.token},body:action==='status'?undefined:JSON.stringify({action,...data}),signal:AbortSignal.timeout(45000),cache:'no-store'});let j;try{j=await r.json();}catch{throw new Error('Gönderim bağlantısı kullanılamıyor. Özeti WhatsApp ile paylaşabilirsiniz.');}if(!r.ok||!j.ok)throw new Error(j.message||'İşlem tamamlanamadı.');return j;}
 if(online)boot=request('status').then(j=>{state.caps=j;state.token=j.token;q('#ai-option').hidden=!j.ai;}).catch(()=>{});
 function bubble(text,user=false){const p=document.createElement('div');p.className='chat-bubble'+(user?' user':'');p.textContent=text;q('#chat-log').append(p);q('#chat-log').scrollTop=q('#chat-log').scrollHeight;}
 function screen(id){for(const x of ['intro','conversation','review'])q('#'+x).hidden=x!==id;}
 function busy(value){state.busy=value;root.querySelectorAll('button').forEach(b=>b.disabled=value);}
 function makeSummary(){return 'FuLab — Yeni proje talebi\n\n'+steps.map(([key,title])=>title+'\n'+(state.answers[key]||'Belirtilmedi')).join('\n\n')+'\n\nÖnerilen sonraki adım: İhtiyaç, kapsam ve uygun çözüm için keşif görüşmesi.\nBu özet teklif veya fiyat taahhüdü değildir.';}
 function review(){q('#summary').value=makeSummary();q('#approved').checked=false;screen('review');q('#summary').focus();q('#send-email').hidden=!state.caps.email;q('#email-unavailable').hidden=!!state.caps.email;q('#share-status').textContent='Özetinizi düzenleyip doğrulayın. Henüz gönderilmedi.';}
 q('#start').addEventListener('click',async()=>{busy(true);if(boot)await boot;state.ai=state.caps.ai&&q('#ai-consent').checked;busy(false);screen('conversation');q('#mode').textContent=state.ai?'Yapay zeka destekli talep asistanı':'Yönlendirmeli talep asistanı · Yapay zeka kullanılmıyor';q('#question').textContent=steps[state.index][1];bubble('Merhaba, ben FuLab dijital talep asistanıyım. İhtiyacınızı birlikte netleştirelim. '+steps[0][1]);q('#answer').focus();});
 q('#chat-form').addEventListener('submit',async e=>{e.preventDefault();const input=q('#answer'),value=input.value.trim();if(!value||state.busy){input.setCustomValidity('Lütfen kısa bir yanıt yazın.');input.reportValidity();return;}input.setCustomValidity('');state.answers[steps[state.index][0]]=value;bubble(value,true);input.value='';state.index++;if(state.index===steps.length){review();return;}q('#progress').textContent='Adım '+(state.index+1)+' / '+steps.length;q('#question').textContent=steps[state.index][1];busy(true);let next=steps[state.index][1];if(state.ai){try{const result=await request('chat',{answers:state.answers,next:state.index,aiConsent:true});next=result.message;}catch{state.ai=false;q('#mode').textContent='Yönlendirmeli mod · Yapay zeka bağlantısı kullanılamadı';q('#chat-status').textContent='Yanıtlarınız korunuyor; standart sorularla devam edebilirsiniz.';}}bubble(next);busy(false);q('#answer').focus();});
 q('#answer').addEventListener('input',()=>q('#answer').setCustomValidity(''));
 q('#restart').addEventListener('click',()=>{state.index=0;state.answers={};q('#chat-log').replaceChildren();q('#progress').textContent='Adım 1 / 5';q('#chat-status').textContent='';screen('intro');q('#start').focus();});
 function approved(){if(!q('#summary').value.trim()){q('#summary').focus();return false;}if(!q('#approved').checked){q('#share-status').textContent='Önce özetin doğruluğunu onaylayın.';q('#approved').focus();return false;}return true;}
 function text(){return q('#summary').value.trim()+'\n\nAd / şirket: '+(q('#lead-name').value.trim()||'Belirtilmedi')+'\nİletişim: '+(q('#lead-contact').value.trim()||'Belirtilmedi');}
 q('#whatsapp-share').addEventListener('click',e=>{if(!approved()){e.preventDefault();return;}e.currentTarget.href='https://wa.me/'+number+'?text='+encodeURIComponent(text());q('#share-status').textContent='WhatsApp’ta mesajı kontrol edip Gönder’e basın. Henüz otomatik gönderim yapılmadı.';});
 q('#download-summary').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob(['\uFEFF'+text()],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='FuLab-Talep-Ozeti.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);q('#share-status').textContent='İndirme başlatıldı. Talebiniz gönderilmedi.';});
 q('#send-email').addEventListener('click',async()=>{if(!approved()||state.busy)return;if(!q('#lead-contact').value.trim()){q('#share-status').textContent='Size dönüş yapabilmemiz için e-posta veya telefon yazın.';q('#lead-contact').focus();return;}busy(true);q('#share-status').textContent='Gönderiliyor…';try{const j=await request('lead',{summary:q('#summary').value.trim(),name:q('#lead-name').value.trim(),contact:q('#lead-contact').value.trim(),approved:true,website:q('#website').value});q('#share-status').textContent=j.message;}catch(e){q('#share-status').textContent=e.message;}finally{busy(false);}});
 q('#email-draft').addEventListener('click',e=>{if(!approved()){e.preventDefault();return;}e.currentTarget.href='mailto:'+cfg.email+'?subject='+encodeURIComponent('FuLab proje talebi')+'&body='+encodeURIComponent(text());q('#share-status').textContent='E-posta uygulamanızda gönderimi sizin tamamlamanız gerekir.';});
})();
